#!/usr/bin/env python3
import json

ch = {
  "book": "Mark",
  "chapter": 12,
  "source": "Marqu - The Hebrew Gospel of Mark v1.2",
  "verses": [],
  "chapter_notes": {
    "summary": "Mark 12 in Hebrew contains several critical one-way translation markers. The most significant are: (1) \u05d0\u05d8\u05d3\u05d9\u05dd ('thorns,' v1) vs. Greek 'fence' \u2014 the vineyard enclosed with thorns that foreshadow the son's crown of thorns, using the OT word from Judges 9:14-15 (the parable where the thorn becomes king); (2) \u05e2\u05d5\u05d1\u05d3\u05d9 \u05d0\u05d3\u05de\u05d4 ('workers of the ground,' v1) echoing Genesis 2-3's adam/adamah creation and rebellion pattern; (3) \u05ea\u05de\u05d5\u05e0\u05d4 ('image,' v16) \u2014 the Second Commandment word, subtly framing Caesar's coin as idolatry; (4) \u05d0\u05de\u05e8 \u05d4\u05d0\u05d3\u05d5\u05df \u05dc\u05d0\u05d3\u05d5\u05e0\u05d9 ('The Lord said to my lord,' v36) \u2014 Psalm 110:1 preserving the critical Hebrew distinction between YHWH (\u05d4\u05d0\u05d3\u05d5\u05df) and the human messianic lord (\u05d0\u05d3\u05d5\u05e0\u05d9), a distinction invisible in Greek where both are \u03ba\u03cd\u03c1\u03b9\u03bf\u03c2; (5) \u05e7\u05e8\u05d1\u05df \u05d0\u05e0\u05d5\u05e9\u05d9 ('human offering,' v33) \u2014 a compact phrase replacing Greek's two sacrifice types; (6) \u05d0\u05e8\u05d5\u05df \u05d4\u05d0\u05d5\u05e6\u05e8 ('treasury ark,' v41) connecting the offering box to the Ark of the Covenant; (7) \u05e4\u05e8\u05d5\u05d8\u05d5\u05ea ('perutot,' v42) using the Jewish coin with no Roman cross-reference (Greek adds the Roman equivalent). The chapter shows consistent use of native Hebrew social terms (\u05d0\u05e0\u05e9\u05d9 \u05d4\u05d5\u05e8\u05d3\u05d5\u05e1, \u05d1\u05ea\u05d9 \u05db\u05e0\u05e1\u05d9\u05d5\u05ea, \u05d9\u05d5\u05d3\u05e2\u05d9 \u05e1\u05e4\u05e8) and legal categories (\u05d7\u05d5\u05d9\u05d9\u05d1, \u05d3\u05d9\u05df) that no back-translator from Greek would produce."
  }
}

def v(num, trans, words, notes=None):
    entry = {"verse": num, "translation": trans, "words": words}
    if notes is None:
        notes = {"one_way_hebrew":[],"greek_deviations":[],"translation_notes":[],"textual_notes":[]}
    entry["notes"] = notes
    ch["verses"].append(entry)

