  [["\u05d5\u05d9\u05e9\u05d5\u05e2","","and Yeshua"],["\u05d4\u05db\u05d9\u05e8","H5234","recognized"],["\u05e9\u05e7\u05e8\u05dd","H8267","their falsehood"],["\u05d5\u05d0\u05de\u05e8","H559","and said"],["\u05dc\u05de\u05d4","H4100","why"],["\u05ea\u05e0\u05e1\u05d5\u05e0\u05d9","H5254","do you test me"],["\u05e9\u05d0\u05d5","H5375","bring"],["\u05dc\u05d9","","me"],["\u05e4\u05e9\u05d5\u05d8","","a coin"],["\u05d0\u05d7\u05d3","H259","one"],["\u05d5\u05d0\u05e8\u05d0\u05d4\u05d5","H7200","and I will look at it"]],
