  [["\u05d5\u05db\u05d0\u05e9\u05e8","","and when"],["\u05e9\u05de\u05e2","H8085","he heard"],["\u05e9\u05d4\u05d5\u05d0","","that he"],["\u05e2\u05e0\u05d4","H6030","answered"],["\u05d1\u05d7\u05db\u05de\u05d4","H2451","wisely"],["\u05d0\u05de\u05e8","H559","said"],["\u05dc\u05d5","","to him"],["\u05d0\u05d9\u05e0\u05d5","H3808","not"],["\u05e8\u05d7\u05d5\u05e7","H7350","far"],["\u05de\u05de\u05dc\u05db\u05d5\u05ea","H4438","from the kingdom of"],["\u05d4\u05e9\u05dd","H8034","HaShem"],["\u05d5\u05de\u05e9\u05dd","H8033","and from then"],["\u05d5\u05d4\u05dc\u05d0\u05d4","","on"],["\u05e9\u05d5\u05dd","","any"],["\u05d0\u05d3\u05dd","H120","man"],["\u05dc\u05d0","H3808","not"],["\u05d4\u05d9\u05d4","H1961","was"],["\u05d1\u05db\u05d5\u05d7","H3581","in strength"],["\u05dc\u05e2\u05e9\u05d5\u05ea","H6213","to make"],["\u05dc\u05d5","","him"],["\u05e9\u05d5\u05dd","","any"],["\u05e9\u05d0\u05dc\u05d4","H7592","question"]]
